let tt = 0;
// === Tab: mySketch ===
// see sketch here https://twitter.com/ippsketch/status/1406239708728991751?s=20
let PERIOD = 300;

let columns = 9;
let rows = 6;
let th, tw, tb, tv; // triangle dimensions

let tri = []; // triangles
let t; //time
let pt; 

function setup() { 
	let minHW = min([windowHeight,windowWidth]);
	createCanvas(minHW,minHW);
	pt = minHW/1000;
	//triangle dimensions
	tw = .5*minHW/rows*2;
	th = .866*tw;
	tv = tw/(2*.866);
	tb = th - tv;
	tt = th/2 - tb;
	colorMode(HSB)

	// create triangles
	for(let x=-floor(columns/2); x<ceil(columns/2); x++){
			for(let y=-floor(rows/2); y<ceil(rows/2); y++){
					let rot = 0;
					if ((x+y+10)%2 == 0) rot=PI;
					let shift = 1;
					tri.push(new Triangle(x*tw/2,y*shift*th+shift*th/2,rot))
			}
	}
}

function draw() {
	t = (frameCount-1)/PERIOD;
	t = t%1;

	background(0)
	translate(width/2,height/2)

	// draw triangles
	for(let i=0; i<tri.length; i++){
		tri[i].draw()
	}
}

class Triangle {
	constructor(_x,_y,_rot){
		this.x = _x;
		this.y = _y;
		this.rot = _rot;
		this.shift = random();
		this.px = []; // path x positions
		this.py = []; // path y positions

		// triangle vertices
		let xv = [0,-tw/2,tw/2,0];
		let yv = [tv,-tb,-tb,tv]

		// define the triangle paths from vertex to vertex
		for (let s=0; s<3; s++){
			for (let n=0; n<PERIOD/3; n++){
				this.px.push(xv[s] + (xv[s+1]-xv[s])*n/(PERIOD/3));
				this.py.push(yv[s] + (yv[s+1]-yv[s])*n/(PERIOD/3));
			}
		}

	} // constructor

	draw (){
		push();
		translate(this.x,this.y)
		rotate(this.rot)
		translate(0,-tt) //difference between grid center and triangle center
		noStroke()
		let sc = .8; //scale

		for  (let a=0; a<3; a++){
			stroke(255)
			strokeWeight(5*pt);
			strokeJoin(ROUND)
			fill(0)


			beginShape();
			for (let f=0; f<150; f++){ // change to f++ for solid line (runs slow here)
				let sgn = 1;
				if (this.shift < .5) sgn = -1;

				let im = (4*PERIOD + round(sgn*(frameCount%PERIOD+f) + a*(this.shift*.5+.3)*(PERIOD/3) + this.shift*PERIOD) )%PERIOD;
				let x = sc*(this.px[im]);
				let y = sc*(this.py[im]);
				vertex(x,y)
			}
			endShape(CLOSE); 
			stroke(0)
			strokeWeight(pt/2)

			noFill();
		}

		pop()
	}
}
